const modules = [
{ name:"01 · SQL Foundations", topics:[
{title:"What is SQL?",intro:"Understand what SQL is and why analysts use it.",definition:"SQL stands for Structured Query Language. It is used to work with data stored in relational databases.",simple:"SQL is a language you use to ask a database questions.",code:"SELECT * FROM Employees;",output:"Shows every column and row in the Employees table.",practice:["Display all records from Employees.","Show only the Name and Salary columns."],hints:["Use SELECT with * to show all columns.","List the required column names after SELECT."],question:"What is SQL mainly used for?",options:["To query and manage relational data","To design website colours","To edit photos","To create computer hardware"],answer:0,why:"SQL queries and manages data in relational databases."},
{title:"Database, DBMS and RDBMS",intro:"Learn how databases store organised information.",definition:"A database is an organised collection of data. A DBMS is software used to create and manage databases. An RDBMS stores related data in tables.",simple:"Database = data collection; DBMS = software to manage it; RDBMS = table-based database system.",code:"CREATE DATABASE CompanyDB;",output:"Creates a database named CompanyDB in systems that support this syntax.",practice:["Write a query to create a database named SchoolDB.","Name one example of an RDBMS."],hints:["Use CREATE DATABASE followed by the database name.","MySQL is one example."],question:"Which option is an RDBMS?",options:["MySQL","HTML","CSS","PowerPoint"],answer:0,why:"MySQL is a relational database management system."},
{title:"Tables, rows and columns",intro:"Understand how relational databases organise records.",definition:"A table stores related records. Each row is one record, and each column describes one attribute shared by those records.",simple:"Rows are records; columns are the fields that describe them.",code:"SELECT Name, Department\\nFROM Employees;",output:"Reads the Name and Department columns from the Employees table.",practice:["Name two columns you might find in an Orders table.","In a Customers table, what does one row represent?"],hints:["Think about information recorded for each order.","One row represents one stored record."],question:"What does one row in a relational table usually represent?",options:["One record","A column definition","A database connection","A query keyword"],answer:0,why:"A row represents one record; columns store the record's individual attributes."},
{title:"SQL data types",intro:"Choose a data type that matches the values a column must store.",definition:"A data type controls what a column can contain and how the database stores or interprets it. The exact names, ranges, and behaviour can differ by database; the examples below follow common MySQL-style types, while this course's practice editor runs SQLite.",simple:"Use character types for text, numeric types for numbers, DATE for a calendar date, and DATETIME for a date plus time. Pick the narrowest type that safely fits the data.",code:"CREATE TABLE TypeDemo (\\n  full_name VARCHAR(50),\\n  country_code CHAR(2),\\n  rating FLOAT,\\n  is_active BOOL,\\n  visit_count INT,\\n  account_id BIGINT,\\n  birth_date DATE,\\n  created_at DATETIME\\n);",output:"Defines variable-length and fixed-length text, approximate and whole numbers, a Boolean-style flag, and date/time columns.",typeGuide:[["VARCHAR(n)","Variable-length text, such as names, emails, or addresses. In VARCHAR(50), 50 is the maximum number of characters allowed, not the number stored every time. Choose a limit that fits your data; limits and counting rules vary by database."],["CHAR(n)","Fixed-length text, useful for values with a consistent length such as a two-letter country code. Some databases pad shorter values; exact comparison and padding behaviour varies."],["FLOAT","Approximate, often fractional numbers when small rounding differences are acceptable, such as measurements. Avoid it for money or exact decimal calculations; use DECIMAL for those."],["BOOL / BOOLEAN","A true/false flag, such as whether an account is active. BOOL is commonly an alias; storage and accepted values depend on the database (for example, MySQL represents BOOLEAN using TINYINT(1))."],["INT","Whole numbers within the database's supported range, such as quantities, ages, or ordinary row counts. Do not use it for identifiers that may exceed its range."],["BIGINT","Whole numbers with a larger range than INT, such as very large event counts or numeric identifiers. Use it only when the INT range is not enough; its precise range depends on signedness and database."],["DATE","A calendar date without a time, such as a birth date or invoice date. It does not represent a time zone or a time of day."],["DATETIME","A calendar date and time together, such as when an order was created. In MySQL DATETIME does not itself convert values between time zones; use a timezone-aware type or a clear UTC convention where needed. SQLite has no dedicated DATETIME storage type and commonly stores date/time values as text or numbers."]],practice:["Create a table named TypeBasics with columns full_name VARCHAR(50), country_code CHAR(2), rating FLOAT, is_active BOOL, visit_count INT, account_id BIGINT, birth_date DATE, and created_at DATETIME.","Create a table named NameLimit with a full_name VARCHAR(50) column. What does the number 50 limit?","Create a table named EventDates with event_date DATE and created_at DATETIME columns."],hints:["Use CREATE TABLE with each column followed by its type. Then run the checker to inspect the table schema.","Use VARCHAR(50) in the column definition. The compiler checks the declared limit in the schema.","DATE stores the calendar date; DATETIME stores a date and time together."],practiceChecks:[{table:"TypeBasics",columns:[["full_name","VARCHAR(50)"],["country_code","CHAR(2)"],["rating","FLOAT"],["is_active","BOOL"],["visit_count","INT"],["account_id","BIGINT"],["birth_date","DATE"],["created_at","DATETIME"]]},{table:"NameLimit",columns:[["full_name","VARCHAR(50)"]]},{table:"EventDates",columns:[["event_date","DATE"],["created_at","DATETIME"]]}],question:"What does the 50 mean in VARCHAR(50)?",options:["The maximum character length allowed for the value","The number of rows in the table","The number of bytes every value always uses","The number of columns in the table"],answer:0,why:"VARCHAR(50) declares a variable-length text column with a maximum length of 50 characters in MySQL. Storage and exact length semantics vary by database."},
{title:"SELECT and FROM",intro:"Retrieve selected columns from a table.",definition:"SELECT specifies which columns to return. FROM specifies the table to read from.",simple:"SELECT says what you want; FROM says where the data lives.",code:"SELECT Name, Salary\\nFROM Employees;",output:"Returns only the Name and Salary columns for all employees.",practice:["Display EmployeeID and Name from Employees.","Display all columns from Orders."],hints:["Write the requested columns after SELECT.","The asterisk means all columns."],question:"Which clause identifies the source table?",options:["FROM","WHERE","ORDER BY","HAVING"],answer:0,why:"FROM names the table or source used by the query."},
{title:"DISTINCT and column aliases",intro:"Remove duplicate results and make column headings clearer.",definition:"DISTINCT removes duplicate rows from the selected result. AS assigns a temporary alias to a column or expression.",simple:"DISTINCT shows unique values; AS gives a result column a clearer name.",code:"SELECT DISTINCT Region AS SalesRegion\\nFROM Orders;",output:"Lists each region once and labels the result column SalesRegion.",practice:["List unique departments from Employees.","Display Salary as MonthlySalary."],hints:["Use DISTINCT before the column name.","Use AS after the expression."],question:"What does DISTINCT do?",options:["Removes duplicate result rows","Sorts rows from highest to lowest","Deletes duplicate rows from the table","Changes a column's data type"],answer:0,why:"DISTINCT affects the query result; it does not delete table data."},
{title:"SQL syntax and comments",intro:"Write readable queries with correct statement endings.",definition:"SQL statements use keywords and identifiers. Comments document code and semicolons commonly mark statement endings.",simple:"Good formatting and comments make SQL easier to read and debug.",code:"-- Show all employees\\nSELECT * FROM Employees;",output:"The comment is ignored by the database; the query returns employee rows.",practice:["Add a comment above a SELECT query.","Write a query that ends with a semicolon."],hints:["In MySQL, -- followed by a space starts a line comment.","Finish the statement with ;"],question:"In MySQL, which symbol pair starts a single-line comment when followed by a space?",options:["--","##","<>","**"],answer:0,why:"MySQL supports -- followed by whitespace for a single-line comment."}
]},
{ name:"02 · Filtering & Sorting", topics:[
{title:"WHERE and comparison operators",intro:"Return only rows that meet a condition.",definition:"WHERE filters rows before grouping. Comparison operators include =, <>, >, <, >= and <=.",simple:"WHERE tells SQL which records you want to keep.",code:"SELECT * FROM Employees\\nWHERE Salary > 45000;",output:"Shows employees whose salary is greater than 45,000.",practice:["Find employees younger than 30.","Find orders with Sales greater than 5000."],hints:["Use < for younger than.","Compare the Sales column to the number."],question:"Which clause filters individual rows?",options:["WHERE","HAVING","GROUP BY","SELECT DISTINCT"],answer:0,why:"WHERE filters rows before aggregation."},
{title:"AND, OR and NOT",intro:"Combine conditions to narrow or broaden results.",definition:"AND requires all conditions to be true. OR requires at least one condition to be true. NOT reverses a condition.",simple:"AND = both; OR = either; NOT = opposite.",code:"SELECT * FROM Employees\\nWHERE Department = 'IT' AND Salary > 50000;",output:"Shows IT employees earning more than 50,000.",practice:["Find IT employees with salary above 40,000.","Find employees in HR or Finance."],hints:["Both conditions must be true in the first question.","Use OR between the two department checks."],question:"With AND, how many conditions must be true for a row to pass?",options:["All joined conditions","At least one condition","No conditions","Only the last condition"],answer:0,why:"AND requires every joined condition to evaluate as true."},
{title:"BETWEEN, IN and NOT IN",intro:"Filter ranges and lists more neatly.",definition:"BETWEEN checks an inclusive range. IN checks membership in a list. NOT IN excludes values in a list.",simple:"BETWEEN = within a range; IN = one of these values.",code:"SELECT * FROM Orders\\nWHERE Sales BETWEEN 1000 AND 5000;",output:"Includes sales from 1,000 through 5,000, including both endpoints.",practice:["Find employees in IT, HR or Sales.","Find orders with sales between 2000 and 7000."],hints:["Use IN with a comma-separated list.","BETWEEN uses AND between the lower and upper values."],question:"Are the endpoints included in BETWEEN?",options:["Yes, both endpoints","No, neither endpoint","Only the lower endpoint","Only the upper endpoint"],answer:0,why:"BETWEEN is inclusive in SQL."},
{title:"LIKE and wildcards",intro:"Search text using a pattern.",definition:"LIKE compares text to a pattern. In SQL, % matches zero or more characters and _ matches exactly one character.",simple:"Use % when the number of characters can vary; use _ for one character.",code:"SELECT * FROM Customers\\nWHERE CustomerName LIKE 'A%';",output:"Finds names that start with A.",practice:["Find names ending in 'a'.","Find names with 'son' anywhere in the name."],hints:["Put % before the ending text.","Place % on both sides of the substring."],question:"In LIKE patterns, what does % represent?",options:["Zero or more characters","Exactly one character","Only a number","A missing value"],answer:0,why:"The percent wildcard matches any sequence of zero or more characters."},
{title:"NULL values",intro:"Find records where a value is missing or unknown.",definition:"NULL represents missing or unknown data. Use IS NULL or IS NOT NULL to test it; = NULL does not work as expected.",simple:"Check missing values with IS NULL, not = NULL.",code:"SELECT * FROM Employees\\nWHERE Department IS NULL;",output:"Returns employees whose Department value is NULL.",practice:["Find customers with no phone number.","Find orders where Status is not NULL."],hints:["Use IS NULL for missing values.","Use IS NOT NULL to exclude missing values."],question:"Which condition correctly finds NULL departments?",options:["Department IS NULL","Department = NULL","Department == NULL","Department LIKE NULL"],answer:0,why:"IS NULL is the correct SQL test for NULL values."},
{title:"ORDER BY and LIMIT",intro:"Sort query results and return a limited number of rows.",definition:"ORDER BY sorts results using ASC (ascending) or DESC (descending). LIMIT restricts how many rows are returned in MySQL.",simple:"ORDER BY sorts; LIMIT controls the result count.",code:"SELECT Name, Salary\\nFROM Employees\\nORDER BY Salary DESC\\nLIMIT 3;",output:"Shows the three highest-salary rows, subject to ties and row ordering.",practice:["Show the 5 lowest salaries.","Display newest orders first."],hints:["Use ASC for lowest to highest.","Sort OrderDate descending for newest first."],question:"Which keyword sorts salary from highest to lowest?",options:["DESC","ASC","LIMIT","DISTINCT"],answer:0,why:"DESC sorts values in descending order."}
]},
{ name:"03 · Data & Table Management", topics:[
{title:"CREATE DATABASE and CREATE TABLE",intro:"Create a database and define a table structure.",definition:"CREATE DATABASE creates a database. CREATE TABLE defines a table and its columns.",simple:"Create the database first, then create tables inside it.",code:"CREATE TABLE Departments (\\n  DepartmentID INT PRIMARY KEY,\\n  DepartmentName VARCHAR(50)\\n);",output:"Creates a Departments table with a primary key and a text column.",practice:["Create a Products table with ProductID and ProductName.","Create a table with an integer ID and decimal price."],hints:["Use CREATE TABLE name (column type, ...).","Use DECIMAL for money-like values that need decimal places."],question:"Which command defines a new table?",options:["CREATE TABLE","ALTER TABLE","UPDATE TABLE","INSERT TABLE"],answer:0,why:"CREATE TABLE creates a table definition."},
{title:"INSERT INTO",intro:"Add new records to a table.",definition:"INSERT INTO adds one or more rows to a table. Naming columns makes the statement clearer and safer.",simple:"INSERT INTO adds data; list columns and then matching values.",code:"INSERT INTO Employees (EmployeeID, Name, Salary)\\nVALUES (101, 'Riya', 42000);",output:"Adds an employee record with ID 101, name Riya and salary 42,000.",practice:["Insert an employee with ID 102 and name Aman.","Insert a product with a price of 299.50."],hints:["The VALUES list must match the column order.","Use quotes around text values."],question:"Which command adds a new row?",options:["INSERT INTO","UPDATE","ALTER TABLE","DROP TABLE"],answer:0,why:"INSERT INTO adds rows to a table."},
{title:"UPDATE and DELETE",intro:"Change existing records and remove selected rows.",definition:"UPDATE modifies existing values. DELETE removes rows that match its WHERE condition; without WHERE it can remove all rows.",simple:"Always check your WHERE condition before running UPDATE or DELETE.",code:"UPDATE Employees\\nSET Salary = 46000\\nWHERE EmployeeID = 101;",output:"Changes the salary for employee 101 only.",practice:["Increase salary to 50,000 for EmployeeID 102.","Delete one order using its OrderID."],hints:["UPDATE uses SET and usually a WHERE filter.","DELETE FROM table WHERE condition removes matching rows."],question:"What can happen if DELETE is run without WHERE?",options:["All rows can be deleted","Only the first row is deleted","The table structure is deleted","Nothing can happen"],answer:0,why:"Without WHERE, DELETE targets every row in the table."},
{title:"ALTER TABLE",intro:"Change the structure of an existing table.",definition:"ALTER TABLE adds, modifies or removes columns and changes table structure. Exact syntax can differ by database system.",simple:"ALTER TABLE changes the design of a table, not just its values.",code:"ALTER TABLE Employees\\nADD Bonus DECIMAL(10,2);",output:"Adds a Bonus column that can store decimal values.",practice:["Add a Bonus column as DECIMAL(10,2).","Rename a column where supported by your database."],hints:["Use ALTER TABLE table_name ADD column_name data_type.","Check your database's syntax for renaming or modifying columns."],question:"Which command changes an existing table's structure?",options:["ALTER TABLE","UPDATE","SELECT","INSERT INTO"],answer:0,why:"ALTER TABLE is used to modify table definitions."},
{title:"DROP, TRUNCATE and DELETE",intro:"Understand three different ways of removing data.",definition:"DELETE removes selected rows, TRUNCATE removes all rows while keeping the table structure, and DROP removes the table object itself.",simple:"DELETE = selected rows; TRUNCATE = all rows; DROP = table itself.",code:"TRUNCATE TABLE TempData;",output:"Removes all rows from TempData while leaving its table structure.",practice:["Remove only cancelled orders using a condition.","Remove a temporary table completely."],hints:["Use DELETE with WHERE for selected rows.","DROP TABLE removes the table definition."],question:"Which command removes the table structure itself?",options:["DROP TABLE","TRUNCATE TABLE","DELETE","SELECT"],answer:0,why:"DROP TABLE removes the table object, including its definition."},
{title:"Constraints and keys",intro:"Protect data quality and relationships.",definition:"Constraints enforce rules. PRIMARY KEY uniquely identifies rows; FOREIGN KEY links tables; UNIQUE prevents duplicate values; NOT NULL requires a value; DEFAULT supplies a default.",simple:"Constraints stop invalid or inconsistent data from being stored.",code:"CREATE TABLE Departments (\\n  DepartmentID INT PRIMARY KEY,\\n  DepartmentName VARCHAR(50) NOT NULL UNIQUE\\n);",output:"DepartmentID must uniquely identify rows; DepartmentName must be present and unique.",practice:["Give EmployeeID a primary key.","Make Email unique and Name not null."],hints:["PRIMARY KEY identifies each row.","UNIQUE and NOT NULL can be applied to appropriate columns."],question:"Which constraint uniquely identifies each row in a table?",options:["PRIMARY KEY","DEFAULT","NOT NULL","CHECK only"],answer:0,why:"A primary key uniquely identifies each row and cannot be NULL."}
]},
{ name:"04 · Aggregate Functions & Grouping", topics:[
{title:"COUNT, SUM, AVG, MIN and MAX",intro:"Calculate summaries from numeric or grouped data.",definition:"COUNT counts rows or non-NULL values, SUM totals values, AVG calculates an average, MIN finds the smallest value and MAX finds the largest.",simple:"These functions summarise a set of rows into a result.",code:"SELECT COUNT(*) AS OrderCount, SUM(Sales) AS TotalSales\\nFROM Orders;",output:"Returns the order row count and total sales.",practice:["Find average salary in Employees.","Find the highest sales value in Orders."],hints:["AVG calculates the mean of non-NULL values.","MAX returns the largest value."],question:"Which aggregate function calculates the mean?",options:["AVG","SUM","COUNT","MAX"],answer:0,why:"AVG calculates the arithmetic average of non-NULL values."},
{title:"GROUP BY",intro:"Calculate a separate summary for each group.",definition:"GROUP BY groups rows with the same values so aggregate functions can calculate results per group.",simple:"Use GROUP BY when you need one summary per region, department or customer.",code:"SELECT Region, SUM(Sales) AS TotalSales\\nFROM Orders\\nGROUP BY Region;",output:"Returns one total sales value for each region.",practice:["Count employees in each department.","Find total profit for each region."],hints:["Put the grouping column in SELECT and GROUP BY.","Use COUNT(*) for row counts."],question:"What does GROUP BY do?",options:["Creates groups for aggregate calculations","Sorts rows alphabetically","Deletes duplicate records","Filters rows before grouping"],answer:0,why:"GROUP BY creates groups on which aggregate functions operate."},
{title:"WHERE vs HAVING",intro:"Know when to filter rows and when to filter groups.",definition:"WHERE filters individual rows before grouping. HAVING filters groups after GROUP BY and is commonly used with aggregate conditions.",simple:"WHERE filters raw rows; HAVING filters grouped results.",code:"SELECT Region, SUM(Sales) AS TotalSales\\nFROM Orders\\nGROUP BY Region\\nHAVING SUM(Sales) > 500000;",output:"Shows only regions whose total sales exceed 500,000.",practice:["Show departments with more than 10 employees.","Calculate sales only for delivered orders, then show regions above 100,000."],hints:["The group-size condition belongs in HAVING.","Filter Status in WHERE before the grouping."],question:"Which clause filters groups after aggregation?",options:["HAVING","WHERE","ORDER BY","FROM"],answer:0,why:"HAVING filters groups after the grouping and aggregate calculation."},
{title:"CASE WHEN and conditional aggregation",intro:"Calculate different measures based on conditions.",definition:"CASE WHEN returns a value based on conditions. Combined with aggregates, it can count or sum only rows that meet a condition.",simple:"CASE lets a query apply if/else logic to data.",code:"SELECT Region,\\n SUM(CASE WHEN Status = 'Returned' THEN 1 ELSE 0 END) AS ReturnedOrders\\nFROM Orders\\nGROUP BY Region;",output:"Counts returned orders for each region.",practice:["Count delivered orders by region.","Sum sales only for orders with Status = 'Delivered'."],hints:["Use CASE WHEN condition THEN value ELSE value END.","Place the CASE expression inside SUM."],question:"What does CASE WHEN provide in SQL?",options:["Conditional logic","A table relationship","A sort direction","A database connection"],answer:0,why:"CASE WHEN returns values according to conditions."},
{title:"NULL values in aggregates",intro:"Understand how missing values affect summaries.",definition:"Most aggregate functions ignore NULL values. COUNT(*) counts rows, while COUNT(column) counts only non-NULL values in that column.",simple:"COUNT(*) counts rows; COUNT(column) skips NULL values in that column.",code:"SELECT COUNT(*) AS AllRows, COUNT(Phone) AS RowsWithPhone\\nFROM Customers;",output:"Shows all customer rows and the count with a non-NULL phone value.",practice:["Count all employees and employees with a non-NULL email.","Find average salary while remembering NULL salaries are ignored."],hints:["Compare COUNT(*) with COUNT(column).","AVG ignores NULL numeric values."],question:"What does COUNT(Phone) count?",options:["Non-NULL Phone values","Every row even when Phone is NULL","Only duplicate phone values","The number of columns"],answer:0,why:"COUNT(column) counts non-NULL values in that column."}
]},
{ name:"05 · SQL Joins", topics:[
{title:"INNER JOIN",intro:"Combine rows that match in both tables.",definition:"INNER JOIN returns rows where the join condition matches in both tables.",simple:"Only matching records from both sides appear.",code:"SELECT e.Name, d.DepartmentName\\nFROM Employees e\\nINNER JOIN Departments d\\n  ON e.DepartmentID = d.DepartmentID;",output:"Shows employees with a matching department record.",practice:["Display order IDs with customer names.","Join Employees to Departments using DepartmentID."],hints:["Match the shared key with ON.","Use aliases to keep table names short."],question:"What does INNER JOIN return?",options:["Rows with matches in both tables","All rows from the left table","All rows from the right table","Every possible row combination"],answer:0,why:"INNER JOIN returns rows satisfying the join condition on both sides."},
{title:"LEFT JOIN",intro:"Keep every row from the left table, even without a match.",definition:"LEFT JOIN returns all left-table rows and matching right-table rows. If there is no right-side match, right-side columns are NULL.",simple:"LEFT JOIN keeps every employee even if they have no department match.",code:"SELECT e.Name, d.DepartmentName\\nFROM Employees e\\nLEFT JOIN Departments d\\n  ON e.DepartmentID = d.DepartmentID;",output:"Shows all employees; DepartmentName is NULL when no department matches.",practice:["Show all customers, including those with no orders.","Find employees whose department is missing."],hints:["Keep Customers on the left to retain every customer.","After a LEFT JOIN, check a right-side key for NULL."],question:"With Employees on the left, which join keeps every employee?",options:["LEFT JOIN","INNER JOIN","CROSS JOIN","Only RIGHT JOIN"],answer:0,why:"LEFT JOIN preserves all rows from the left table."},
{title:"RIGHT JOIN and FULL OUTER JOIN",intro:"Understand other ways to preserve unmatched records.",definition:"RIGHT JOIN preserves all rows from the right table. FULL OUTER JOIN preserves unmatched rows from both sides, but MySQL does not support FULL OUTER JOIN directly.",simple:"RIGHT keeps the right side; FULL keeps both sides where supported.",code:"SELECT e.Name, d.DepartmentName\\nFROM Employees e\\nRIGHT JOIN Departments d\\n  ON e.DepartmentID = d.DepartmentID;",output:"Shows all departments, including departments with no matching employee.",practice:["Return all departments even if they have no employees.","How could you emulate FULL OUTER JOIN in MySQL?"],hints:["Put the table you want to preserve on the right for RIGHT JOIN.","A UNION of left and right join results is one possible emulation."],question:"Which join preserves all rows from the right table?",options:["RIGHT JOIN","INNER JOIN","CROSS JOIN","SELF JOIN"],answer:0,why:"RIGHT JOIN keeps every right-side row."},
{title:"CROSS JOIN and SELF JOIN",intro:"Create combinations or relate rows within the same table.",definition:"CROSS JOIN returns combinations of rows from two tables. SELF JOIN joins a table to itself using aliases.",simple:"CROSS = combinations; SELF = same table used twice.",code:"SELECT e.Name AS Employee, m.Name AS Manager\\nFROM Employees e\\nLEFT JOIN Employees m ON e.ManagerID = m.EmployeeID;",output:"Matches employees to manager records from the same Employees table.",practice:["Show each employee with their manager name.","If table A has 3 rows and B has 4 rows, how many rows can CROSS JOIN produce?"],hints:["Use two aliases for the same table.","CROSS JOIN row count is the product of the two row counts."],question:"A CROSS JOIN of 3 rows and 4 rows can return how many rows?",options:["12","7","4","3"],answer:0,why:"Every row from the first table pairs with every row from the second: 3 × 4 = 12."},
{title:"Join multiple tables and avoid duplicates",intro:"Combine several tables without accidentally inflating totals.",definition:"Multiple joins connect related tables through keys. Incorrect join conditions or one-to-many relationships can multiply rows and inflate aggregates.",simple:"Check the relationship and row count before trusting totals after joins.",code:"SELECT o.OrderID, c.CustomerName, p.ProductName\\nFROM Orders o\\nJOIN Customers c ON o.CustomerID = c.CustomerID\\nJOIN Products p ON o.ProductID = p.ProductID;",output:"Combines order, customer and product details using their keys.",practice:["Join Orders and Customers using CustomerID.","Explain why joining one order to multiple order lines can repeat OrderID."],hints:["Each ON clause should connect the correct keys.","One-to-many joins can produce several result rows for one parent row."],question:"What can an incorrect join condition cause?",options:["Unexpected duplicate rows and inflated totals","Automatic data cleaning","Guaranteed faster queries","All NULL values to disappear"],answer:0,why:"Incorrect or many-to-many matching can multiply rows and inflate aggregates."}
]},
{ name:"06 · String, Date & Numeric Functions", topics:[
{title:"UPPER, LOWER, CONCAT and TRIM",intro:"Change text case, combine strings and remove surrounding spaces.",definition:"UPPER and LOWER change case, CONCAT joins strings, and TRIM removes leading and trailing spaces.",simple:"String functions help clean names and combine text fields.",code:"SELECT UPPER(Name), CONCAT(FirstName, ' ', LastName), TRIM(City)\\nFROM Customers;",output:"Returns uppercase names, combined names and trimmed city values.",practice:["Display customer names in lowercase.","Combine FirstName and LastName with a space."],hints:["LOWER changes text to lowercase.","Use CONCAT with a space string between name fields."],question:"Which function removes leading and trailing spaces?",options:["TRIM","CONCAT","UPPER","REPLACE"],answer:0,why:"TRIM removes spaces from the beginning and end of a string."},
{title:"LTRIM, RTRIM, REPLACE, LEFT, RIGHT and SUBSTRING",intro:"Remove spaces, replace text and extract parts of a string.",definition:"LTRIM removes leading spaces, RTRIM trailing spaces, REPLACE substitutes text, LEFT and RIGHT extract edge characters, and SUBSTRING extracts a section.",simple:"Choose the function based on where the text you need is located.",code:"SELECT RTRIM('SQL   '), REPLACE('SQL Basic','Basic','Advanced'), LEFT('Database',4);",output:"Returns 'SQL', 'SQL Advanced' and 'Data'.",practice:["Use RIGHT to get the last 4 characters of Database.","Replace Basic with Advanced in SQL Basic."],hints:["RIGHT extracts from the end of a string.","REPLACE takes the original string, old text and new text."],question:"What does LEFT('Database', 4) return?",options:["Data","base","Database","D"],answer:0,why:"LEFT returns the first four characters from the string."},
{title:"LOCATE, INSTR and string length",intro:"Find the position of text and measure strings.",definition:"LOCATE and INSTR find the position of a substring in a string in MySQL. LENGTH returns byte length; CHAR_LENGTH returns character count.",simple:"Use a search function for position and a length function for size.",code:"SELECT LOCATE('base', 'Database') AS Position, CHAR_LENGTH('SQL');",output:"LOCATE returns 5; CHAR_LENGTH returns 3.",practice:["Find the position of 'SQL' in 'Learn SQL now'.","Return the character count of 'Database'."],hints:["Positions in MySQL strings start at 1.","Database contains eight characters."],question:"In MySQL, what is LOCATE('base', 'Database')?",options:["5","4","0","8"],answer:0,why:"The substring 'base' starts at character position 5 in 'Database'."},
{title:"Date functions",intro:"Extract dates and calculate time differences.",definition:"Date functions can extract year or month, format dates and calculate differences. Available functions and formats depend on the database system.",simple:"Date functions help analyse monthly trends, year-to-date results and time gaps.",code:"SELECT YEAR(OrderDate) AS OrderYear, MONTH(OrderDate) AS OrderMonth\\nFROM Orders;",output:"Returns year and month numbers for each order date.",practice:["Display orders placed in 2025.","Group order counts by month."],hints:["Use YEAR(OrderDate) to extract the year.","For monthly counts, group by a year-month expression."],question:"In MySQL, what does MONTH(OrderDate) return?",options:["The month number","The day of the month","The year","The number of days between dates"],answer:0,why:"MONTH returns a month number from 1 to 12 for a valid date."},
{title:"ROUND, ABS, CEIL and FLOOR",intro:"Round numbers and work with numeric values.",definition:"ROUND rounds to a chosen precision, ABS returns a non-negative magnitude, CEIL rounds up to an integer and FLOOR rounds down to an integer.",simple:"These functions help format or transform numeric calculations.",code:"SELECT ROUND(12.567, 2), ABS(-8), CEIL(4.2), FLOOR(4.8);",output:"Returns 12.57, 8, 5 and 4.",practice:["Round 456.789 to two decimal places.","Return the absolute value of -25."],hints:["ROUND accepts a number and decimal-place count.","ABS returns distance from zero."],question:"What does ROUND(12.567, 2) return?",options:["12.57","12.56","13","12.567"],answer:0,why:"Rounded to two decimal places, 12.567 becomes 12.57."}
]},
{ name:"07 · Subqueries & CTEs", topics:[
{title:"Scalar and multi-row subqueries",intro:"Use one query's result inside another query.",definition:"A scalar subquery returns one value. A multi-row subquery returns multiple values and is often used with IN or other set comparisons.",simple:"A subquery is a query nested inside another query.",code:"SELECT Name, Salary\\nFROM Employees\\nWHERE Salary > (SELECT AVG(Salary) FROM Employees);",output:"Shows employees earning above the company average salary.",practice:["Find products priced above the average product price.","Find employees in departments listed in another query."],hints:["The average salary subquery returns one value.","Use IN when the inner query may return multiple department IDs."],question:"What must a scalar subquery return?",options:["One value","One full table only","Exactly two rows","No values"],answer:0,why:"A scalar subquery returns a single value."},
{title:"Subqueries with WHERE and HAVING",intro:"Compare rows or groups with a query result.",definition:"Subqueries in WHERE can filter individual rows; subqueries in HAVING can compare aggregate groups against a value or set returned by another query.",simple:"First understand what the inner query returns, then compare it in the outer query.",code:"SELECT Region, SUM(Sales) AS TotalSales\\nFROM Orders\\nGROUP BY Region\\nHAVING SUM(Sales) > (SELECT AVG(RegionTotal) FROM (SELECT SUM(Sales) AS RegionTotal FROM Orders GROUP BY Region) x);",output:"Shows regions whose total sales exceed the average of regional sales totals (MySQL syntax).",practice:["Find employees earning above the overall average.","Find regions whose total sales exceed a chosen threshold."],hints:["Check whether the inner query returns one value or many.","The HAVING condition should compare an aggregate to the intended threshold."],question:"Which clause is commonly used to filter grouped aggregate results?",options:["HAVING","WHERE only","FROM only","ORDER BY only"],answer:0,why:"HAVING is designed to filter groups after aggregation."},
{title:"Correlated subqueries",intro:"Run an inner query that refers to the current outer row.",definition:"A correlated subquery references a column from the outer query, so its result depends on the current outer row.",simple:"The inner query uses a value from the outer query row.",code:"SELECT e.Name, e.Salary\\nFROM Employees e\\nWHERE e.Salary > (SELECT AVG(e2.Salary) FROM Employees e2 WHERE e2.DepartmentID = e.DepartmentID);",output:"Shows employees earning above the average salary in their own department.",practice:["Find products priced above the average price in their category.","Find employees paid more than their department average."],hints:["The inner query must refer to the outer row's category or department.","Use different aliases for the two table references."],question:"Why is a subquery called correlated?",options:["It references a value from the outer query","It always returns exactly one row","It cannot use WHERE","It permanently changes the table"],answer:0,why:"A correlated subquery refers to columns from the outer query."},
{title:"EXISTS and NOT EXISTS",intro:"Test whether a related record exists.",definition:"EXISTS is true when its subquery returns at least one row. NOT EXISTS is true when the subquery returns no rows.",simple:"Use EXISTS to check for a match without needing to return the matching rows.",code:"SELECT c.CustomerID, c.CustomerName\\nFROM Customers c\\nWHERE NOT EXISTS (SELECT 1 FROM Orders o WHERE o.CustomerID = c.CustomerID);",output:"Returns customers who have no matching order.",practice:["Find customers who have placed at least one order.","Find products that have never been ordered."],hints:["EXISTS tests for at least one matching row.","NOT EXISTS is useful for finding missing related records."],question:"What does EXISTS test?",options:["Whether the subquery returns at least one row","Whether the subquery returns exactly 10 rows","Whether a column is numeric","Whether rows are sorted"],answer:0,why:"EXISTS evaluates to true if the subquery returns at least one row."},
{title:"CTEs and recursive CTE concepts",intro:"Give a named result to a query step.",definition:"A common table expression (CTE) is a named temporary result defined with WITH for one statement. A recursive CTE refers to itself and can handle hierarchical or iterative patterns in supported systems.",simple:"CTEs let you break a long query into readable steps.",code:"WITH RegionalSales AS (\\n  SELECT Region, SUM(Sales) AS TotalSales\\n  FROM Orders GROUP BY Region\\n)\\nSELECT * FROM RegionalSales WHERE TotalSales > 500000;",output:"Creates a named regional summary and then filters it.",practice:["Create a CTE that counts orders by status.","Use a CTE to calculate total sales by region."],hints:["Put the inner SELECT inside WITH name AS (...).","The outer SELECT reads from the CTE name."],question:"What is the main purpose of a CTE?",options:["To name and organise a query result for one statement","To permanently create a table every time","To delete duplicate data","To replace every JOIN"],answer:0,why:"A CTE names a result set that can make a query easier to read and organise."}
]},
{ name:"08 · Window Functions", topics:[
{title:"OVER and PARTITION BY",intro:"Calculate across related rows without collapsing them.",definition:"Window functions use OVER to define the rows involved. PARTITION BY splits those rows into groups while retaining individual result rows.",simple:"GROUP BY reduces rows into groups; window functions can keep each row and add a group calculation.",code:"SELECT EmployeeID, DepartmentID, Salary,\\n AVG(Salary) OVER (PARTITION BY DepartmentID) AS DeptAvg\\nFROM Employees;",output:"Shows each employee alongside the average salary in their department.",practice:["Show each order with its region's total sales using a window sum.","Show each employee with department average salary."],hints:["Add OVER after the aggregate function.","Use PARTITION BY for calculations that restart per department or region."],question:"What does PARTITION BY do in a window function?",options:["Divides rows into calculation groups","Deletes rows outside the group","Sorts the final output only","Creates a permanent table"],answer:0,why:"PARTITION BY defines groups over which the window calculation operates."},
{title:"ROW_NUMBER, RANK and DENSE_RANK",intro:"Assign positions to rows, including when values tie.",definition:"ROW_NUMBER gives every row a unique sequential number. RANK gives tied rows the same rank and leaves gaps. DENSE_RANK gives tied rows the same rank without gaps.",simple:"Choose the ranking function based on how you want ties handled.",code:"SELECT Name, Salary,\\n DENSE_RANK() OVER (ORDER BY Salary DESC) AS SalaryRank\\nFROM Employees;",output:"Ranks salaries from highest to lowest, with equal salaries sharing a rank and no gaps.",practice:["Rank employees by salary within each department.","Find the second distinct highest salary."],hints:["Use PARTITION BY DepartmentID for per-department ranking.","Dense rank is useful when tied values share a rank without gaps."],question:"Which function assigns a unique sequential number to every row?",options:["ROW_NUMBER","RANK","DENSE_RANK","COUNT"],answer:0,why:"ROW_NUMBER assigns a different sequential number to each row in the window ordering."},
{title:"LAG and LEAD",intro:"Compare a row with a previous or next row.",definition:"LAG accesses a value from a preceding row in the window order. LEAD accesses a value from a following row.",simple:"LAG looks back; LEAD looks forward.",code:"SELECT OrderDate, Sales,\\n LAG(Sales) OVER (ORDER BY OrderDate) AS PreviousSales\\nFROM Orders;",output:"Adds the previous row's sales value according to OrderDate ordering.",practice:["Show each month's sales next to the previous month's sales.","Compare each employee salary with the next salary in sorted order."],hints:["Use LAG for previous rows.","Specify ORDER BY inside OVER to define the sequence."],question:"Which function accesses a value from a preceding row?",options:["LAG","LEAD","RANK","ROUND"],answer:0,why:"LAG accesses a value from a preceding row in the window order."},
{title:"Running totals and moving averages",intro:"Track cumulative and rolling metrics.",definition:"A running total accumulates values through the current row. A moving average calculates an average over a sliding set of rows.",simple:"Running total keeps adding; moving average averages a recent window.",code:"SELECT OrderDate, Sales,\\n SUM(Sales) OVER (ORDER BY OrderDate ROWS UNBOUNDED PRECEDING) AS RunningSales\\nFROM Orders;",output:"Calculates cumulative sales in OrderDate order.",practice:["Calculate running sales by date.","Calculate a three-row moving average."],hints:["Use SUM as a window function for a cumulative total.","A moving average needs a frame covering the intended number of rows."],question:"What does a running total show?",options:["Cumulative sum up to the current row","Average of all future rows only","Number of distinct columns","Smallest value in a group"],answer:0,why:"A running total accumulates values up to and including the current row in the chosen order."},
{title:"Top-N per group and ties",intro:"Find the highest-ranked records inside each category or region.",definition:"Top-N per group ranks rows within each group and filters the rank. The choice of ROW_NUMBER, RANK or DENSE_RANK determines how ties are handled.",simple:"Partition by the group, order by the metric, then filter the rank.",code:"WITH Ranked AS (\\n SELECT CustomerID, Region, SUM(Sales) AS TotalSales,\\n DENSE_RANK() OVER (PARTITION BY Region ORDER BY SUM(Sales) DESC) AS rnk\\n FROM Orders GROUP BY CustomerID, Region\\n)\\nSELECT * FROM Ranked WHERE rnk <= 3;",output:"Returns customers ranked in the top three sales positions within each region, including ties.",practice:["Find the top 3 customers by sales in each region, including ties.","Explain the difference between top 3 rows and top 3 ranks."],hints:["Group sales by customer and region before ranking.","Use a ranking function with PARTITION BY Region."],question:"What does PARTITION BY Region do for a ranking window?",options:["Restarts ranking separately for each region","Ranks all regions as one group","Removes all tied rows","Sorts regions alphabetically only"],answer:0,why:"PARTITION BY Region creates an independent ranking sequence for each region."}
]},
{ name:"09 · Professional SQL Concepts", topics:[
{title:"CASE WHEN and IF expressions",intro:"Return different values depending on conditions.",definition:"CASE WHEN evaluates conditions and returns the value for the first matching branch. MySQL also has IF(condition, true_value, false_value).",simple:"Use conditional expressions to label or categorise records.",code:"SELECT OrderID,\\n CASE WHEN Sales >= 5000 THEN 'High' ELSE 'Standard' END AS SalesBand\\nFROM Orders;",output:"Labels each order as High or Standard based on sales.",practice:["Label salary as High when it is above 60,000.","Create a status label for profit greater than zero."],hints:["Put the condition after WHEN.","Finish CASE with END."],question:"Which keyword closes a CASE expression?",options:["END","STOP","CLOSE","DONE"],answer:0,why:"SQL CASE expressions finish with END."},
{title:"Views",intro:"Save a reusable query as a database view.",definition:"A view is a named query that can be used like a virtual table. A normal view stores the query definition, not a separate copy of the result data.",simple:"A view saves a query so you can reuse it with a simple SELECT.",code:"CREATE VIEW HighValueOrders AS\\nSELECT OrderID, CustomerID, Sales\\nFROM Orders WHERE Sales > 5000;",output:"Creates a view that exposes orders with sales above 5,000.",practice:["Create a view for delivered orders.","Query the HighValueOrders view."],hints:["Start with CREATE VIEW view_name AS SELECT ...","You can query a view using SELECT just like a table."],question:"What does a normal database view primarily store?",options:["A query definition","A permanent duplicate of every result row","Only indexes","A backup file"],answer:0,why:"A standard view stores a query definition that runs when queried."},
{title:"Indexes and query performance",intro:"Learn how databases can find rows more efficiently.",definition:"An index is a data structure that can speed up lookups and sorting for suitable queries, but it uses storage and can make writes slower.",simple:"Indexes can make reads faster, but too many indexes have costs.",code:"CREATE INDEX idx_orders_customer\\nON Orders(CustomerID);",output:"Creates an index on CustomerID to help suitable queries find matching rows.",practice:["Suggest a column to index for frequent customer order lookups.","Name one trade-off of adding an index."],hints:["Think about columns often used in WHERE or JOIN conditions.","Indexes take storage and must be maintained during writes."],question:"What is a common trade-off of adding indexes?",options:["Faster reads but extra storage and write overhead","All queries become faster","The table no longer needs a primary key","The index automatically cleans invalid data"],answer:0,why:"Indexes can speed up reads but consume storage and add maintenance overhead."},
{title:"Transactions, COMMIT and ROLLBACK",intro:"Group changes into a unit of work.",definition:"A transaction groups database operations. COMMIT saves the transaction's changes; ROLLBACK undoes uncommitted changes where transaction support applies.",simple:"COMMIT keeps the changes; ROLLBACK cancels uncommitted changes.",code:"START TRANSACTION;\\nUPDATE Accounts SET Balance = Balance - 500 WHERE AccountID = 1;\\nUPDATE Accounts SET Balance = Balance + 500 WHERE AccountID = 2;\\nCOMMIT;",output:"Shows a transaction pattern for transferring 500 between two accounts; production code must also validate errors and balances.",practice:["Explain why two transfer updates should be in one transaction.","Which command undoes uncommitted changes?"],hints:["A transaction helps keep related changes together.","Use the command opposite to COMMIT before changes are committed."],question:"What does COMMIT do?",options:["Makes transaction changes permanent","Removes the table","Sorts the rows","Creates an index"],answer:0,why:"COMMIT finalises the current transaction's changes."},
{title:"EXPLAIN and query optimisation",intro:"Inspect how the database plans to run a query.",definition:"EXPLAIN shows information about the query execution plan, such as access methods and indexes considered. Optimisation uses this evidence to improve query performance.",simple:"Use EXPLAIN to investigate how SQL plans to fetch data.",code:"EXPLAIN SELECT * FROM Orders\\nWHERE CustomerID = 101;",output:"Shows a plan for finding orders for customer 101; exact output depends on the database and schema.",practice:["Run EXPLAIN on a query that filters by CustomerID.","Name one way to make a query easier to optimise."],hints:["EXPLAIN goes before the SELECT in MySQL.","Filter only the columns and rows you need when possible."],question:"What is EXPLAIN commonly used for?",options:["Inspecting a query execution plan","Adding a new column","Inserting a row","Changing a user's password"],answer:0,why:"EXPLAIN provides information about how the database plans to execute a query."}
]},
{ name:"10 · Business Case SQL Practice", topics:[
{title:"SQL problem-solving practice",intro:"Build a habit of solving data problems in a clear order.",definition:"A SQL practice set uses filtering, aggregation, joins, subqueries and analytical patterns to answer business questions.",simple:"Read the requirement, identify the table and columns, write the query, then check edge cases.",code:"SELECT Region, SUM(Sales) AS TotalSales\\nFROM Orders\\nWHERE Status = 'Delivered'\\nGROUP BY Region\\nORDER BY TotalSales DESC;",output:"Summarises delivered sales by region, highest total first.",practice:["Count delivered orders by region.","Find customers who placed more than five non-cancelled orders."],hints:["Filter cancelled orders before counting.","Group by the required reporting dimension."],question:"What should you identify before writing a SQL answer?",options:["Required output, tables and relevant columns","Only the query's final semicolon","A random index name","The dashboard colour theme"],answer:0,why:"Understanding the required output, tables and columns helps determine the correct query structure."},
{title:"Second-highest and Nth-highest values",intro:"Solve common ranking problems.",definition:"The second-highest distinct value is the second value after duplicates are removed and values are sorted descending. Ranking functions or subqueries can solve this.",simple:"Clarify whether the requirement is the second row or the second distinct value.",code:"SELECT MAX(Salary) AS SecondHighestSalary\\nFROM Employees\\nWHERE Salary < (SELECT MAX(Salary) FROM Employees);",output:"Returns the second-highest distinct salary when at least two distinct salary values exist.",practice:["Find the third-highest distinct salary.","Explain what happens when every employee has the same salary."],hints:["First find the maximum, then search below that value.","If there is no lower distinct value, the outer MAX returns NULL."],question:"What does the query return when all employees have the same salary?",options:["NULL","The same salary as second-highest","Zero automatically","Every employee row"],answer:0,why:"No salary is below the maximum, so MAX over the filtered set returns NULL."},
{title:"Top customers or products by region",intro:"Rank sales performance within each region.",definition:"This problem typically aggregates sales by region and customer or product, then uses a window ranking function to identify the top results in each region.",simple:"Aggregate first, rank second, filter ranks last.",code:"WITH CustomerTotals AS (\\n SELECT Region, CustomerID, SUM(Sales) AS TotalSales\\n FROM Orders GROUP BY Region, CustomerID\\n), Ranked AS (\\n SELECT *, DENSE_RANK() OVER (PARTITION BY Region ORDER BY TotalSales DESC) AS rnk\\n FROM CustomerTotals\\n)\\nSELECT * FROM Ranked WHERE rnk <= 3;",output:"Returns customers in the top three sales ranks per region, including ties.",practice:["Find top 3 products per region including ties.","Explain why aggregation should happen before ranking customers."],hints:["The customer total needs one row per customer and region.","Window functions rank the aggregated results."],question:"Which clause restarts the rank within each region?",options:["PARTITION BY Region","GROUP BY Sales only","ORDER BY Region only","LIMIT 3"],answer:0,why:"PARTITION BY Region creates a separate ranking window for every region."},
{title:"Duplicate records and missing matches",intro:"Find repeated data and records without related rows.",definition:"GROUP BY with HAVING COUNT(*) > 1 can identify repeated key values. LEFT JOIN plus a NULL check or NOT EXISTS can find records without a related match.",simple:"Duplicates are repeated keys; missing matches have no related row.",code:"SELECT Email, COUNT(*) AS Copies\\nFROM Customers\\nGROUP BY Email\\nHAVING COUNT(*) > 1;",output:"Lists email values that appear more than once.",practice:["Find duplicate OrderIDs.","Find customers who have never placed an order."],hints:["Group by the field you suspect is duplicated.","Use NOT EXISTS or LEFT JOIN to find customers without orders."],question:"Which pattern commonly finds duplicated values?",options:["GROUP BY column HAVING COUNT(*) > 1","ORDER BY column LIMIT 1","SELECT DISTINCT column only","DROP TABLE"],answer:0,why:"Grouping by the candidate key and requiring a count greater than one identifies repeated values."},
{title:"Sales, profit and monthly trend case studies",intro:"Turn business questions into measurable SQL outputs.",definition:"Business case queries convert raw transactions into metrics such as monthly sales, profit, return rate, customer totals and regional performance.",simple:"Translate the business question into metric, time period, grouping and filters.",code:"SELECT YEAR(OrderDate) AS OrderYear, MONTH(OrderDate) AS OrderMonth,\\n SUM(Sales) AS TotalSales, SUM(Profit) AS TotalProfit\\nFROM Orders\\nGROUP BY YEAR(OrderDate), MONTH(OrderDate)\\nORDER BY OrderYear, OrderMonth;",output:"Returns monthly sales and profit totals in chronological order.",practice:["Calculate monthly sales for delivered orders.","Find regions with sales above 500,000 and average profit above 10,000."],hints:["Group by both year and month to separate years correctly.","Use HAVING for conditions on SUM and AVG."],question:"Which clause filters a region by SUM(Sales) after grouping?",options:["HAVING","WHERE","FROM","DISTINCT"],answer:0,why:"HAVING filters groups using aggregate conditions such as SUM(Sales)."},
{title:"Explain queries and edge cases",intro:"Communicate your SQL solution clearly.",definition:"A strong SQL explanation states the approach, key clauses, assumptions and edge cases such as NULLs, ties, duplicates and missing matches.",simple:"Do not only give the query—explain why it works and what happens in unusual cases.",code:"-- 1. Filter rows\\n-- 2. Group and aggregate\\n-- 3. Filter groups with HAVING\\n-- 4. Sort the result\\nSELECT Region, SUM(Sales) AS TotalSales\\nFROM Orders\\nGROUP BY Region\\nHAVING SUM(Sales) > 500000\\nORDER BY TotalSales DESC;",output:"Shows regions above the sales threshold, ordered from highest total to lowest.",practice:["Explain WHERE versus HAVING in your own words.","Name two edge cases to check for a top-N query."],hints:["Explain the query in the same order SQL logically processes it.","Think about equal values and missing data."],question:"What is a useful edge case for a top-N ranking query?",options:["Tied values at the cutoff","The name of the SQL file","The page background colour","The length of the table name only"],answer:0,why:"Ties at the cutoff can change whether more than N rows should be returned."}
]}
];

const $ = id => document.getElementById(id);
let currentModule = 0, currentTopic = 0, quizChecked = false;
const progressStorageKey = "sqlbite.completedTopics.v1";
let sqlEngine;
const allTopics = () => modules.flatMap((m,mi)=>m.topics.map((t,ti)=>({...t,mi,ti,moduleName:m.name})));
const topicKey = (mi,ti) => JSON.stringify([modules[mi].name,modules[mi].topics[ti].title]);
function showProgressStorageMessage(message){
  const status=$("progressStorageMessage");
  status.textContent=message;
  status.hidden=!message;
}
function loadCompletedTopics(){
  let saved;
  try{saved=localStorage.getItem(progressStorageKey);}
  catch(error){
    console.error("Unable to read saved course progress.",error);
    showProgressStorageMessage("Progress cannot be loaded in this browser. Completed topics will be tracked for this visit only.");
    return new Set();
  }
  if(!saved)return new Set();
  try{
    const parsed=JSON.parse(saved);
    if(!Array.isArray(parsed))throw new Error("Saved progress must be a list of topic keys.");
    const validKeys=new Set(allTopics().map(topic=>topicKey(topic.mi,topic.ti)));
    return new Set(parsed.filter(key=>typeof key==="string"&&validKeys.has(key)));
  }catch(error){
    console.error("Unable to restore saved course progress.",error);
    showProgressStorageMessage("Saved progress could not be read. New completions will be tracked from this visit.");
    return new Set();
  }
}
const completed = loadCompletedTopics();
function searchableTopicText(module,topic){
  return [module.name,topic.title,topic.intro,topic.definition,topic.simple,topic.code,topic.output,topic.question,...topic.practice].join(" ").toLowerCase();
}
function renderSidebar(){
  const search = ($("topicSearch").value || "").trim().toLowerCase();
  $("moduleList").innerHTML = modules.map((m,mi)=>{
    const filtered = m.topics.map((t,ti)=>({...t,ti})).filter(t=>{
      return searchableTopicText(m,t).includes(search);
    });
    if(!filtered.length) return "";
    return `<div class="module-group"><p class="module-name">${m.name}</p>${filtered.map(t=>{
      const key=topicKey(mi,t.ti), active=mi===currentModule&&t.ti===currentTopic;
      return `<button class="topic-btn ${active?'active':''} ${completed.has(key)?'done':''}" data-mi="${mi}" data-ti="${t.ti}"><span class="topic-num">${String(t.ti+1).padStart(2,'0')}</span><span>${escapeHTML(t.title)}</span></button>`;
    }).join("")}</div>`;
  }).join("");
  $("moduleList").querySelectorAll(".topic-btn").forEach(b=>b.addEventListener("click",()=>loadTopic(+b.dataset.mi,+b.dataset.ti)));
  $("topicSearchEmpty").hidden = $("moduleList").children.length !== 0;
  updateProgress();
}
function escapeHTML(s){return s.replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function loadTopic(mi,ti){
  currentModule=mi;currentTopic=ti;quizChecked=false;
  const m=modules[mi],t=m.topics[ti];
  $("moduleLabel").textContent=m.name.toUpperCase();
  $("topicPosition").textContent=`TOPIC ${String(ti+1).padStart(2,"0")} OF ${m.topics.length}`;
  $("lessonTitle").textContent=t.title;$("lessonIntro").textContent=t.intro;
  $("definitionText").textContent=t.definition;$("simpleText").textContent=t.simple;
  const typeGuide=$("typeGuide");typeGuide.replaceChildren();typeGuide.hidden=!t.typeGuide;
  if(t.typeGuide){
    const heading=document.createElement("h3");heading.textContent="Common SQL data types and when to use them";
    const intro=document.createElement("p");intro.className="type-guide-intro";intro.textContent="Type names and exact ranges vary between database systems. These examples use common MySQL conventions.";
    const list=document.createElement("dl");list.className="type-guide-list";
    t.typeGuide.forEach(([name,description])=>{
      const term=document.createElement("dt");term.textContent=name;
      const detail=document.createElement("dd");detail.textContent=description;
      list.append(term,detail);
    });
    typeGuide.append(heading,intro,list);
  }
  $("exampleIntro").textContent="Read the query, then compare it with the expected result.";
  $("exampleCode").textContent=t.code.replace(/\\n/g,"\n");$("exampleOutput").textContent=t.output;
  $("practiceList").innerHTML=t.practice.map((p,i)=>`<li>${escapeHTML(p)}<br><button class="hint" data-hint="${i}">Show hint</button><p class="hint-text" id="hint${i}">${escapeHTML(t.hints[i]||"Break the question into smaller steps.")}</p></li>`).join("");
  $("practiceList").querySelectorAll(".hint").forEach(b=>b.addEventListener("click",()=>{const p=$("hint"+b.dataset.hint);p.classList.toggle("show");b.textContent=p.classList.contains("show")?"Hide hint":"Show hint";}));
  $("practiceQuestionSelect").replaceChildren(...t.practice.map((question,index)=>{
    const option=document.createElement("option");option.value=String(index);option.textContent=`Question ${index+1}`;return option;
  }));
  updatePracticeQuestion();
  $("quizQuestion").textContent=t.question;
  $("quizOptions").innerHTML=t.options.map((o,i)=>`<label class="quiz-option"><input type="radio" name="quizAnswer" value="${i}"><span>${escapeHTML(o)}</span></label>`).join("");
  $("quizFeedback").textContent="";$("quizFeedback").className="quiz-feedback";
  const key=topicKey(mi,ti);$("markComplete").disabled=completed.has(key);$("markComplete").textContent=completed.has(key)?"Topic completed ✓":"Mark topic complete ✓";
  $("completionMessage").textContent=completed.has(key)?"Nice work — this topic is marked complete.":"Learn it, try it, then take the quiz.";
  $("nextTopic").textContent=(ti===m.topics.length-1&&mi===modules.length-1)?"Course complete ✓":"Next topic →";
  renderSidebar();
}
function updatePracticeQuestion(){
  const topic=modules[currentModule].topics[currentTopic],index=Number($("practiceQuestionSelect").value)||0;
  $("practicePrompt").textContent=topic.practice[index]||"Write a query for this practice question.";
  $("practiceHint").textContent=topic.hints[index]||"Break the question into smaller steps and test the query in the editor.";
  $("runPracticeQuery").textContent=topic.practiceChecks?.[index]?"Run & check":"Run query";
  $("practiceHint").hidden=true;$("showPracticeHint").textContent="Show hint";
  $("practiceSqlEditor").value="";$("practiceSqlResult").replaceChildren();
  $("practiceSqlStatus").textContent=sqlEngine?"SQL engine ready. Queries run only in this browser.":"Loading the SQL practice engine…";
  $("practiceSqlStatus").className="practice-sql-status";
}
function createPracticeDatabase(){
  const database=new sqlEngine.Database();
  database.exec(`
    CREATE TABLE Employees (EmployeeID INTEGER PRIMARY KEY, Name TEXT, Department TEXT, Salary REAL, Age INTEGER, HireDate TEXT);
    INSERT INTO Employees VALUES
      (1, 'Asha Verma', 'Analytics', 62000, 28, '2022-03-14'),
      (2, 'Ravi Shah', 'Sales', 54000, 34, '2020-11-02'),
      (3, 'Mina Das', 'Analytics', 71000, 31, '2023-06-19');
    CREATE TABLE Customers (CustomerID INTEGER PRIMARY KEY, Name TEXT, Country TEXT);
    INSERT INTO Customers VALUES (1, 'Northwind Cafe', 'India'), (2, 'Maple Market', 'Canada');
    CREATE TABLE Orders (OrderID INTEGER PRIMARY KEY, CustomerID INTEGER, OrderDate TEXT, Amount REAL, Status TEXT);
    INSERT INTO Orders VALUES (101, 1, '2025-01-15', 240.50, 'shipped'), (102, 1, '2025-02-04', 520.00, 'shipped'), (103, 2, '2025-02-18', 115.25, 'pending');
    CREATE TABLE Products (ProductID INTEGER PRIMARY KEY, ProductName TEXT, Category TEXT, Price REAL);
    INSERT INTO Products VALUES (1, 'Pro Keyboard', 'Electronics', 120.00), (2, 'Desk Lamp', 'Home', 45.50), (3, 'Notebook', NULL, 8.00);
  `);
  return database;
}
function renderPracticeResults(results){
  const container=$("practiceSqlResult");container.replaceChildren();
  results.forEach(result=>{
    const table=document.createElement("table");table.className="practice-result-table";
    const head=document.createElement("thead"),headerRow=document.createElement("tr");
    result.columns.forEach(column=>{const cell=document.createElement("th");cell.textContent=column;headerRow.append(cell);});
    head.append(headerRow);
    const body=document.createElement("tbody");
    result.values.forEach(row=>{
      const rowElement=document.createElement("tr");
      row.forEach(value=>{const cell=document.createElement("td");cell.textContent=value===null?"NULL":String(value);rowElement.append(cell);});
      body.append(rowElement);
    });
    table.append(head,body);container.append(table);
  });
}
function checkDataTypeSchema(database,check){
  const schema=database.exec(`PRAGMA table_info("${check.table.replace(/"/g,'""')}")`)[0];
  if(!schema)return false;
  const normalizeType=type=>type.replace(/\s+/g,"").toUpperCase().replace(/^INTEGER$/,"INT").replace(/^BOOLEAN$/,"BOOL");
  const actual=schema.values.map(row=>[String(row[1]).toLowerCase(),normalizeType(String(row[2]))]);
  const expected=check.columns.map(([name,type])=>[name.toLowerCase(),normalizeType(type)]);
  return actual.length===expected.length&&actual.every((column,index)=>column[0]===expected[index][0]&&column[1]===expected[index][1]);
}
function runPracticeQuery(){
  const status=$("practiceSqlStatus"),output=$("practiceSqlResult"),source=$("practiceSqlEditor").value.trim();
  output.replaceChildren();
  if(!source){status.textContent="Write a SQL query before running it.";status.className="practice-sql-status incorrect";return;}
  let database;
  try{
    database=createPracticeDatabase();
    const results=database.exec(source);
    renderPracticeResults(results);
    const topic=modules[currentModule].topics[currentTopic],index=Number($("practiceQuestionSelect").value)||0;
    const check=topic.practiceChecks?.[index];
    if(check){
      if(checkDataTypeSchema(database,check)){
        status.textContent="Correct! The table and all column data types match the requested schema.";
        status.className="practice-sql-status correct";
      }else{
        status.textContent=`Not quite yet. Check the ${check.table} table name, column names, order, and data types, then try again.`;
        status.className="practice-sql-status incorrect";
      }
    }else{
      const rows=results.reduce((total,result)=>total+result.values.length,0);
      status.textContent=`SQL executed successfully${results.length?` and returned ${rows} row(s)`:", with no result rows"}. This question does not have automatic answer checking yet; compare the output with the prompt.`;
      status.className="practice-sql-status neutral";
    }
  }catch(error){
    status.textContent=`Incorrect — SQL error: ${error.message}`;
    status.className="practice-sql-status incorrect";
  }finally{
    if(database)database.close();
  }
}
function updateProgress(){
  const total=allTopics().length;$("progressText").textContent=`${completed.size} / ${total}`;
  $("progressBar").style.width=`${total?completed.size/total*100:0}%`;
  $("progressBar").setAttribute("aria-valuemax",String(total));
  $("progressBar").setAttribute("aria-valuenow",String(completed.size));
}
$("topicSearch").addEventListener("input",()=>{
  const term=$("topicSearch").value.trim().toLowerCase();
  renderSidebar();
  if(!term)return;
  const topics=modules.flatMap((module,mi)=>module.topics.map((topic,ti)=>({module,mi,topic,ti})));
  const match=topics.find(({module,topic})=>module.name.toLowerCase().includes(term)||topic.title.toLowerCase().includes(term))
    ||topics.find(({module,topic})=>searchableTopicText(module,topic).includes(term));
  if(match&&(match.mi!==currentModule||match.ti!==currentTopic))loadTopic(match.mi,match.ti);
});
$("practiceQuestionSelect").addEventListener("change",updatePracticeQuestion);
$("showPracticeHint").addEventListener("click",()=>{
  const hint=$("practiceHint");hint.hidden=!hint.hidden;
  $("showPracticeHint").textContent=hint.hidden?"Show hint":"Hide hint";
});
$("runPracticeQuery").addEventListener("click",runPracticeQuery);
$("checkQuiz").addEventListener("click",()=>{
  const t=modules[currentModule].topics[currentTopic],sel=document.querySelector('input[name="quizAnswer"]:checked');
  if(!sel){$("quizFeedback").textContent="Please select an answer first.";$("quizFeedback").className="quiz-feedback bad";return;}
  quizChecked=true;
  if(+sel.value===t.answer){$("quizFeedback").textContent="Correct! "+t.why;$("quizFeedback").className="quiz-feedback good";}
  else{$("quizFeedback").textContent="Not quite. Try again. Hint: "+t.why;$("quizFeedback").className="quiz-feedback bad";}
});
$("markComplete").addEventListener("click",()=>{
  completed.add(topicKey(currentModule,currentTopic));
  try{
    localStorage.setItem(progressStorageKey,JSON.stringify([...completed]));
    showProgressStorageMessage("");
  }catch(error){
    console.error("Unable to save course progress.",error);
    showProgressStorageMessage("Progress is updated for this visit, but could not be saved in this browser.");
  }
  renderSidebar();
  $("markComplete").disabled=true;$("markComplete").textContent="Topic completed ✓";
  $("completionMessage").textContent="Great! You can revisit this topic anytime.";
});
$("nextTopic").addEventListener("click",()=>{
  if(currentTopic<modules[currentModule].topics.length-1)loadTopic(currentModule,currentTopic+1);
  else if(currentModule<modules.length-1)loadTopic(currentModule+1,0);
  else { $("completionMessage").textContent="You reached the end of the course. Revisit any topic from the left menu.";window.scrollTo({top:0,behavior:"smooth"}); }
});
$("copyQuery").addEventListener("click",async()=>{
  const text=$("exampleCode").textContent;
  try{await navigator.clipboard.writeText(text);$("copyQuery").textContent="Copied!";setTimeout(()=>$("copyQuery").textContent="Copy query",1200);}
  catch(e){$("copyQuery").textContent="Select and copy";const r=document.createRange();r.selectNodeContents($("exampleCode"));const s=window.getSelection();s.removeAllRanges();s.addRange(r);}
});
$("year").textContent=new Date().getFullYear();
loadTopic(0,0);
if(typeof initSqlJs!=="function"){
  $("practiceSqlStatus").textContent="Could not load the SQLite engine. Check your internet connection and reload this page.";
  $("practiceSqlStatus").className="practice-sql-status incorrect";
}else{
  initSqlJs({locateFile:file=>`https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.10.3/${file}`}).then(engine=>{
    sqlEngine=engine;
    $("runPracticeQuery").disabled=false;
    $("practiceSqlStatus").textContent="SQL engine ready. Queries run only in this browser.";
  }).catch(error=>{
    console.error("Could not load the lesson SQL engine.",error);
    $("practiceSqlStatus").textContent=`Could not load the SQL engine: ${error.message}`;
    $("practiceSqlStatus").className="practice-sql-status incorrect";
  });
}
